function taskOrder(tasks, prerequisites) {
    const done = new Array(tasks).fill(false);
    const order = [];
    while (order.length < tasks) {
        let chosen = -1;
        for (let task = 0; task < tasks && chosen === -1; task++) {
            if (done[task])
                continue;
            let ready = true;
            for (const [before, after] of prerequisites)
                if (after === task && !done[before])
                    ready = false;
            if (ready)
                chosen = task;
        }
        if (chosen === -1)
            return [];
        done[chosen] = true;
        order.push(chosen);
    }
    return order;
}

function taskOrder(tasks, prerequisites) {
    const blocked = new Array(tasks).fill(0);
    const unlocks = Array.from({ length: tasks }, () => []);
    for (const [before, after] of prerequisites) {
        unlocks[before].push(after);
        blocked[after]++;
    }
    const heap = [];
    const push = (value) => {
        heap.push(value);
        let i = heap.length - 1;
        while (i > 0) {
            const parent = (i - 1) >> 1;
            if (heap[parent] <= heap[i])
                break;
            [heap[parent], heap[i]] = [heap[i], heap[parent]];
            i = parent;
        }
    };
    const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length > 0) {
            heap[0] = last;
            let i = 0;
            while (true) {
                const left = 2 * i + 1;
                const right = left + 1;
                let smallest = i;
                if (left < heap.length && heap[left] < heap[smallest])
                    smallest = left;
                if (right < heap.length && heap[right] < heap[smallest])
                    smallest = right;
                if (smallest === i)
                    break;
                [heap[smallest], heap[i]] = [heap[i], heap[smallest]];
                i = smallest;
            }
        }
        return top;
    };
    for (let task = 0; task < tasks; task++)
        if (blocked[task] === 0)
            push(task);
    const order = [];
    while (heap.length > 0) {
        const task = pop();
        order.push(task);
        for (const next of unlocks[task]) {
            blocked[next]--;
            if (blocked[next] === 0)
                push(next);
        }
    }
    return order.length === tasks ? order : [];
}
